3085	                .{ .surface = self },
3086	                .key_sequence,
3087	                .{ .trigger = entry.key_ptr.* },
3088	            ) catch |err| {
3089	                log.warn(
3090	                    "failed to notify app of key sequence err={}",
3091	                    .{err},
3092	                );
3093	            };
